#!/usr/bin/env python3
"""Chinese R10 report from frozen paired results. Does not select or run experiments."""
import csv,json,statistics as st
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'results/round10_projection';C=BASE/'main_10s';B=BASE/'mechanism';MODES=['plain_only','plain_extra','projection_escape']
def csvrows(p):return list(csv.DictReader(p.open()))
def short(c):return 'Bromberger' if 'Bromberger' in c else 'SMT_random' if 'SMT_random' in c else 'convert'
def avg(rows,key):return st.mean(float(r[key]) for r in rows)
def main():
 rows=csvrows(C/'sessions.csv');cases=sorted({r['instance'] for r in rows});decision=json.loads((C/'decision.json').read_text());assert not decision['enter_D'];val=json.loads((BASE/'validation/PASSED.json').read_text());ba=json.loads((B/'AUDIT.json').read_text());ca=json.loads((C/'AUDIT.json').read_text());plan=json.loads((C/'plan.json').read_text());audits=[json.loads(p.read_text()) for p in (C/'audit').glob('*.json')]
 text=['# 第十轮：覆盖反馈投影机制与实验报告','','**结论：停止扩大实验，不进入 30 秒验证。** 新模块确实能在 Bromberger 产生一些优于同周期普通模型的合法候选，但未稳定改善 10 秒累计覆盖。其余两个真实公式没有交付任何投影候选。没有满足事前门槛的独立正面案例，Bromberger 的首个输出相对 plain_extra 还有可重复退步。本轮不调整频率、投影规模、评分或 timeout 来追求正例。','','## 范围、实现与冻结','','基于 `86f97e4` 新建 `round10-feedback-projection`；实验代码和协议冻结在 `'+plan['commit']+'`。原第九轮 plain_fixed / macro_fair_retry、Global 实现、第一至九轮结果及覆盖评测器不变。新增 `FeedbackProjection`、`ProjectionGuidedExplorer` 和独立 `projection_online_probe` 入口，未接入原正式采样器。没有运行 HighDiv、全量历史模型重放、900 秒实验或新 OR/bit/变量块策略。','','覆盖使用原公式 AST、短路访问、Int 低 64 位、原分母。S0 恢复原前缀并去重提交已有合法种子；种子覆盖不是本轮生成收益，恢复、解析和初始化计时。每个周期先运行普通探索，在同一覆盖版本比较普通与额外候选；按新增 covered、再 observed、再普通优先选取。所有 SAT 赋值、重复、失败、迟到和未胜出候选都有日志；内部候选不更新正式状态，零收益输出不被过滤。未启用可选待选池，未胜出的普通模型保存为内部证据但不计正式吞吐。','','每次从最多 32 个变量的有界静态依赖评分中，取最高分八个里的最多三个；评分为相关节点单侧缺口数乘近期稳定系数。使用最近最多四份不同正式模型的去重投影，临时查询完整 F 加投影差异，其他变量自由。引导使用独立常驻 simple solver，临时约束 push/pop；局部 UNSAT 不进入全局不可达缓存。初始互补机会及至少四个不同零增益普通候选触发，额外尝试后至少四次普通机会。每次最多一次额外查询，阶段额度 50 ms、会话总额 10%，评估/写出预留 15 ms，最终交付另有预留。完整参数见《第十轮实验协议》。','','**实际时间限制：** 本次会话额外总额度均未超限；但 convert/seed-0 的引导 solver 初始化是不可中断的原生调用，令一次阶段实际达到 **54.366512 ms**，超过 50 ms **4.366512 ms**。该阶段没有发起投影 check，也没有产生投影候选，原普通见证仍及时提交；全部成本计入，状态为 `initialization_budget`。因此当前实现在原生初始化上不能保证严格的 50 ms 墙钟硬截止，不能把“审计通过”表述成所有时间上限都未突破。没有通过删掉该会话或补跑消除此限制。','','## 正确性、机制小样本与可复核性','','Release 和 ASan/UBSan 均通过 **16 项 C++ + 104 项 Python 测试**（含此前 15/97 项）。测试覆盖短路/共享表达式、Bool/大整数、非选定变量自由、等式协同变化、临时约束撤销、局部 UNSAT/Unknown、晚到排除、已有普通见证保留、种子去重、首次观察配对、内部覆盖隔离和边际恒等式。Sanitizer 保留 leak 检查，仅复用已冻结的外部 Z3 抑制项。','','阶段 B：三个开发公式 prefix-1/10 × 两 seed × 三模式各 1 秒，另三个合成状态 × 三模式各 0.5 秒，共 **45 会话**。所有会话保留；独立 Manual 审计 '+str(ba['validated_models'])+' 次求值，通过全部覆盖与输出一致性检查，额外阶段/总额超限均为 0。Bromberger 投影实际赢出 48 次，同周期净替换增益合计 316 bit；额外普通赢出 8 次、109 bit。但这不是端到端效益证明。SMT_random 在 1 秒下三模式均无新输出；convert 没有投影 SAT。合成可变投影、固定投影、可变但无新覆盖三例通过；合成成功不算真实正例。','','阶段 C：三个原开发公式 prefix-1 × seed 0/1/2 × 三模式，共 **27 个 10 秒会话**。每批两个完整三模式组，最多六路；组内顺序轮换、批间屏障。独立审计在采样结束后运行，核验 '+str(ca['validated_models'])+' 次模型求值；所有原始模型合法、完整 seen0/seen1 和候选评分一致、截止提交与去重一致、边际和等于累计增益。额外阶段超限 1 次、会话总额超限 0 次。没有缺失/进程失败、没有静默删除零输出会话。补充审计还核对原始 prefix/seed 文本、三个配置同状态同波次，以及 864 个归档成员的逐文件哈希。','','## 10 秒累计覆盖','','下表是三个 seed 的均值；括号为按原分母计算的百分点增量，不是相对百分比。不同公式的 bit 不能代表相同难度，会话是配对单位，三个动作/模型不是独立重复。','','| 案例 | plain_only | plain_extra | projection_escape | 投影 − extra，均值 bit |','|---|---:|---:|---:|---:|']
 for case in cases:
  vals={m:[r for r in rows if r['instance']==case and r['mode']==m] for m in MODES}
  text.append('| '+short(case)+' | '+' | '.join(f"{avg(vals[m],'gain'):.2f}（{avg(vals[m],'gain_percentage_points'):.3f} pp）" for m in MODES)+f" | {avg(vals['projection_escape'],'gain')-avg(vals['plain_extra'],'gain'):+.2f} |")
 text+=['','| 案例 | 投影 vs only 胜/平/负 | 投影 vs extra 胜/平/负 | extra vs only 胜/平/负 |','|---|---|---|---|']
 pairs=csvrows(C/'paired_summary.csv')
 for case in cases:
  by={r['contrast']:r for r in pairs if r['instance']==case};text.append('| '+short(case)+' | '+' | '.join(f"{by[k]['win']}/{by[k]['tie']}/{by[k]['loss']}" for k in ('projection_escape - plain_only','projection_escape - plain_extra','plain_extra - plain_only'))+' |')
 text+=['','逐 seed 的新增 bit（0、1、2 顺序）：','','| 案例 | plain_only | plain_extra | projection_escape |','|---|---|---|---|']
 for case in cases:text.append('| '+short(case)+' | '+' | '.join(', '.join(r['gain'] for r in sorted(rows,key=lambda r:int(r['seed'])) if r['instance']==case and r['mode']==m) for m in MODES)+' |')
 text+=['','SMT_random/seed-2 的 plain_extra 没有新输出，收益按零保留。SMT_random 的投影配置相对 extra 平均多 1004 bit，但所有 21 次实际投影 check 都返回原始 Unknown（canceled/cancelled，按时间证据推断为局部超时，未作不可达结论），整个收益来自普通候选；不能将其正差归因于投影。相同 seed 不保证后续模型序列相同，本次没有证据将序列差异统称为随机噪声，也没有额外因果消融。convert 三次额外阶段均在初始化消耗后退出，没有发起投影 check；其普通轨迹差异同样不构成投影收益证据。','','![三种模式的固定时间覆盖增量](../results/round10_projection/main_10s/figures/coverage_curves.png)','','曲线为三 seed 均值，阴影为最小至最大值，不是置信区间。PDF/SVG 同目录可导出。','','## 早期质量、供给与普通探索机会成本','','Bromberger 的前三配置首个输出增益分别为 only `[207,231,207]`、extra `[289,251,271]`、投影 `[207,231,207]`。投影在 seed-0/2 相对 extra 分别下降 28.37% / 23.62%，触发预冻结的可重复早期退步条件。投影前 1/2/5/10 个输出在该例与 only 相同，extra 在首个输出占优但后续前缀不一定占优；不能用一个前缀替代整条曲线。','','| 案例 / 模式 | 新正式模型均值 | 每秒不同合法已验证候选 | 普通 SAT 均值 | 普通完整阶段秒均值 | 额外完整秒均值 |','|---|---:|---:|---:|---:|---:|']
 for case in cases:
  for mode in MODES:
   a=[r for r in rows if r['instance']==case and r['mode']==mode]
   text.append('| '+short(case)+' / '+mode+' | '+' | '.join(f'{avg(a,k):.3f}' for k in ('outputs','supply_per_second','plain_sat','plain_seconds','extra_spent'))+' |')
 text+=['','候选供给分母采用完整进程墙钟，包括初始化与析构；只计截止前完成验证的不同合法赋值，包含未被选择的内部候选，但这些不算正式覆盖。全部九会话的平均候选供给，投影为 only 的 112.37%、extra 的 114.05%；固定时间覆盖分别为 98.77%、102.06%。这满足 90% 的总体保护阈值，但不代表每个实例或 seed 都不受损。投影使普通阶段实际可用墙钟减少，却不一定减少 SAT 数：增量历史和正式种子改变后，单次求解难度也改变。不能把更多普通输出解释为投影模块本身更快。','','前缀逐例值与未达到标记均保留在 sessions.csv / pairs.csv；convert 的很多 5/10 样本前缀未达到，SMT_random/extra/seed-2 连一个都未达到。未达到不补齐、不按成功者均值隐藏。首次正收益时间也逐会话保留：SMT_random 在 only 为 7.562/5.388/3.507 秒、extra 为 6.575/4.131/未达到、投影为 4.253/7.049/5.924 秒。','','## 投影候选是否值得成本','','真正的投影候选全部来自 Bromberger：730 次 SAT 中仅 51 份是首次出现的不同合法候选。23 次与已正式输出模型重复，另外 656 次是此前内部已经见过的候选；最近四个正式投影不同，不等于全会话新模型。730 份保存候选里 30 次在当时 S 下有正收益，最终赢出并及时输出 27 次，同周期相对普通候选的 covered 净增益合计 **253 bit**。这个差是冻结同一 S 的局部竞争差，不是端到端覆盖的可加因果贡献。额外普通在该例 411 次 check 中 406 SAT（其余原始 Unknown，控制层按记录归类超时），406 份均为新候选，11 次胜出，净替换增益 182 bit。','','跨九会话全部额外成本：投影 **1.962 秒**，extra **3.402 秒**；其中投影反馈 0.043 秒、第二 solver 初始化 0.154 秒、check 0.723 秒、约束构造 0.020 秒、模型补全 0.356 秒、原公式验证 0.084 秒、独立在线评估和候选日志约 0.264 秒。extra 的 check 为 2.417 秒、模型补全 0.476 秒、验证 0.073 秒、评估约 0.192 秒。分项和完整阶段存在包含关系，不能重复求和；剩余包含日志、维护和包装开销。失败、初始化退出、重复与未胜出候选全部保留在完整成本中。','','投影局部净替换差 / 全部额外耗时约 128.95 bit/s，extra 约 53.49 bit/s；这是本批已发生动作的描述比值，分母覆盖失败和管理成本，**不是端到端吞吐优势**，也不是两个模块的独立因果贡献。触发次数、会话轨迹与成功概率不同。尤其 Bromberger 的三个投影会话累计覆盖全部低于 only；更高的局部比值没有转化为任务收益。','','## 高原是否减少','','| 案例 / 模式 | 零收益正式输出均值 | 最长连续零收益均值 | 最长无覆盖增长秒均值 |','|---|---:|---:|---:|']
 for case in cases:
  for mode in MODES:
   a=[r for r in rows if r['instance']==case and r['mode']==mode];text.append('| '+short(case)+' / '+mode+' | '+' | '.join(f'{avg(a,k):.3f}' for k in ('zero_outputs','longest_zero_run','longest_plateau_seconds'))+' |')
 text+=['','所有九会话合计：only 3128 份正式输出中 2830 零收益，extra 2671/2356，投影 3463/3175。投影相对 only 多了 335 份输出，却多了 345 份零收益，正收益输出从 298 减为 288；没有减少覆盖重复。Bromberger 的最长连续零收益从均值 185.67 升至 231.67，最长高原相对 only 也略长。convert 的高原变短只由普通模型贡献，不能归为投影成功。','','## 对六个问题的明确回答','','1. **210 个零覆盖模型的重复规律：** 210 份都没有新单侧观察，变量变化数 3–29、相对最近四份均为新值的变量数中位数 0；稳定变量仍关联大量缺口，所有状态有历史合法可达见证。但变化变量的静态缺口相关计数与全部变化数相同，不能证明这种评分比一般变量变化更有效。详细证据见单独的重复覆盖原因报告。','2. **是否更容易得到互补模型：** 仅 Bromberger 有直接正例，27 个正式投影赢家；另外两例均无投影见证。没有未带覆盖反馈的随机投影消融，不能分离反馈排序、稳定偏好和投影差异各自作用，更不能宣称普遍更容易。','3. **是否比同预算多一次普通探索更值得：** 未得到可推广的肯定答案。Bromberger 虽 2 胜 1 负，平均仍少 29.33 bit；convert 平均少 27.33 bit；SMT_random 的正差没有投影候选支持。局部动作更便宜不等于固定会话收益更好。','4. **是否损害普通探索与早期质量：** 总体供给未系统下降，但普通可用墙钟减少，Bromberger 第一份新输出相对 extra 有两 seed 超过 10% 的退步。不能作“零机会成本”的保证。','5. **净覆盖与高原改善多少：** 九会话 bit 和相对 only 为 −1746、相对 extra 为 +2842；这些跨公式合计只是描述。Bromberger 和 convert 相对 extra 平均为负，SMT_random 正差不含投影输出。高原没有稳定减少，零收益输出反而增多。','6. **算法贡献判断：** 当前是有界启发式和可审计实现，缺少跨独立结构的稳定收益，不能宣称独立理论性质或已验证的算法优势。保留代码、失败数据及初始化硬截止限制，停止扩大实验。','','预冻结门槛要求至少两个独立公式满足两 seed 胜、均值正且有及时投影严格赢家，并保护早期覆盖及总体供给。此次正面独立公式 **0**，早期保护失败；`decision.json` 的 `enter_D=false`。不启动 30 秒、不另挑新案例、不增加预算或目标。','','## 重放与交付','','构建及完整回归：','','```bash','cmake -S . -B build/round10/release -DCMAKE_BUILD_TYPE=Release -DZ3_PREFIX=/tmp/lia-highdiv-frozen/venv','cmake --build build/round10/release -j6','bash scripts/test_projection_build.sh release','cmake -S . -B build/round10/sanitize -DCMAKE_BUILD_TYPE=Debug -DZ3_PREFIX=/tmp/lia-highdiv-frozen/venv \\\n  -DCMAKE_CXX_FLAGS="-O1 -g -fsanitize=address,undefined -fno-omit-frame-pointer" \\\n  -DCMAKE_EXE_LINKER_FLAGS="-fsanitize=address,undefined"','cmake --build build/round10/sanitize -j6','bash scripts/test_projection_build.sh sanitize','```','','三模式单会话示例（必须使用新的 OUT 目录）：','','```bash','build/round10/release/projection_online_probe benchmarks/SMT_random_LIA_ex14600_2600_100.smt2 \\\n  projection_escape 10 0 /tmp/projection-replay \\\n  results/round3_snapshots/states/SMT_random_LIA_ex14600_2600_100.smt2/prefix-1/prefix.values \\\n  results/round3_snapshots/states/SMT_random_LIA_ex14600_2600_100.smt2/prefix-1/seed.values','```','','将模式替换为 plain_only / plain_extra，分别给出独立输出目录。每会话原始完整命令已保存在 runs.jsonl。批次需要 clean tracked 工作树；新输出目录不允许覆盖：','','```bash','export HIGHDIV_ROOT=/tmp/lia-highdiv-frozen','PY=/tmp/lia-highdiv-frozen/venv/bin/python3','$PY scripts/run_projection_pairs.py --stage B --binary build/round10/release/projection_online_probe --output /tmp/round10-B-replay','$PY scripts/audit_projection_pairs.py /tmp/round10-B-replay --jobs 6','$PY scripts/analyze_projection_pairs.py /tmp/round10-B-replay','$PY scripts/run_projection_pairs.py --stage C --binary build/round10/release/projection_online_probe --output /tmp/round10-C-replay','$PY scripts/audit_projection_pairs.py /tmp/round10-C-replay --jobs 6','$PY scripts/analyze_projection_pairs.py /tmp/round10-C-replay','```','','C 入口还校验仓库归档 B 审计通过；D 入口被失败门槛禁止。本轮这些重放命令仅作为交付，不在报告完成后自动再运行。已有证据复核（先从 raw.tar.gz 恢复未跟踪的 raw/；原审计目录已存在时不要覆盖，使用副本）：','','```bash','$PY scripts/audit_projection_inputs.py results/round10_projection/main_10s','python3 scripts/report_exploration_redundancy.py','python3 scripts/plot_projection_pairs.py results/round10_projection/main_10s','python3 scripts/report_projection_pairs.py','```','','数据：results/round10_analysis/ 保留离线逐模型、逐变量、可达见证与成本；results/round10_projection/mechanism/ 和 main_10s/ 保留 plan、runs、raw.tar.gz、archive、完整逐会话独立审计、sessions/curves/costs/pairs/summary/paired_summary CSV、门槛结果和可导出图。公式/快照/二进制/源代码/评测器/Z3 哈希绑定在计划，模型身份与写完时间在原日志。冻结的源代码摘要：`'+plan['source_sha256']+'`。']
 (ROOT/'docs/第十轮覆盖反馈投影机制与实验报告.md').write_text('\n'.join(text)+'\n')
if __name__=='__main__':main()
